namespace CSharpToTypeScript.Tests;

/// <summary>
/// Task 15：接口与 implements 发射。
/// 断言修订说明（以 IR/发射器实测为准）：
/// - 方法名为 Java camelCase（既有约定，Task 10/11/13/14 实证）：bar，非 Bar；
/// - 接口属性在 IR 中为自动生成访问器方法对（getX()/setX(value)，IsAutoGenerated = true），
///   合并发射为 TS 属性声明：仅 getter → readonly X: number;；get+set → X: number;；
///   只写属性（仅 setter）保留 setter 方法 + 诊断注释；
/// - implements/extends 类型经 Java→TS 映射：框架接口（Comparable/AutoCloseable → object）
///   在 heritage 位置降级为全局类型 Object（`object` 关键字非法，tsc TS2552，TS 5.x/7.x
///   一致）；用户接口未命中类型表时原样发射，泛型实参逐段映射（IBase&lt;Integer&gt; →
///   IBase&lt;number&gt;）。
/// </summary>
public class TsInterfaceEmissionTests : TsConversionTestBase
{
    [Fact]
    public void Interface_Declaration_Emits_Export_Interface()
    {
        var result = Convert("""
interface IFoo
{
    int Bar();
}
""");
        Assert.True(result.Success);
        Assert.Contains("export interface IFoo {", result.GeneratedCode);
        // 方法名 Java camelCase（bar，非计划原断言 Bar——既有约定，以实测为准）
        Assert.Contains("bar(): number;", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Class_Implements_Interface_Emits_Implements()
    {
        var result = Convert("""
interface IFoo
{
    int Bar();
}
class Foo : IFoo
{
    public int Bar() { return 1; }
}
""");
        Assert.True(result.Success);
        Assert.Contains("export class Foo implements IFoo", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Interface_With_Properties_Emits_Properties()
    {
        var result = Convert("""
interface IPoint
{
    int X { get; }
    int Y { get; }
}
""");
        Assert.True(result.Success);
        Assert.Contains("export interface IPoint", result.GeneratedCode);
        // 接口属性发射为 readonly X: number;（仅 getter → 只读属性）
        Assert.Contains("readonly X: number;", result.GeneratedCode);
        Assert.Contains("X: number;", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Extends_Interface_Emits_Extends()
    {
        var result = Convert("""
interface IBase
{
    int A();
}
interface IDerived : IBase
{
    int B();
}
""");
        Assert.True(result.Success);
        Assert.Contains("export interface IDerived extends IBase", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Property_With_Getter_And_Setter_Emits_Non_Readonly()
    {
        var result = Convert("""
interface IPoint
{
    int X { get; set; }
}
""");
        Assert.True(result.Success);
        // get+set → 非只读属性（无 readonly 前缀）
        Assert.Contains("    X: number;", result.GeneratedCode);
        Assert.DoesNotContain("readonly X: number;", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Write_Only_Property_Keeps_Setter_With_Diagnostic()
    {
        var result = Convert("""
interface IWritable
{
    int Z { set; }
}
""");
        Assert.True(result.Success);
        // 只写属性（仅 setter）无 TS 对应形态：保留 setter 方法 + 诊断注释
        Assert.Contains("/* cs2j: write-only property Z: no TS counterpart; kept as setter method */", result.GeneratedCode);
        Assert.Contains("setZ(value: number): void;", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Class_Implements_Mapped_Framework_Interface_Emits_Object()
    {
        // Task 14 审查登记：implements Comparable<S> 不走 MapType 原样发射、非法 TS。
        // 本任务修复：heritage 类型经 Java→TS 映射；映射结果为 object 时降级为全局
        // 类型 Object（implements 位置 `object` 关键字非法，tsc TS2552）。
        var result = Convert("""
class Point : IComparable<Point>
{
    public int CompareTo(Point other) { return 0; }
}
class Auto : System.IDisposable
{
    public void Dispose() { }
}
""");
        Assert.True(result.Success);
        Assert.Contains("export class Point implements Object", result.GeneratedCode);
        Assert.Contains("export class Auto implements Object", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Class_Implements_Generic_Interface_Emits_Mapped_Args()
    {
        var result = Convert("""
interface IRepo<T>
{
    T Find();
}
class Foo : IRepo<int>
{
    public int Find() { return 0; }
}
""");
        Assert.True(result.Success);
        // 用户接口未命中类型表：原样保留，泛型实参逐段映射（Integer → number）
        Assert.Contains("export class Foo implements IRepo<number>", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Extends_Generic_Interface_Emits_Mapped_Args()
    {
        var result = Convert("""
interface IBase<T>
{
    T A();
}
interface IDerived : IBase<int>
{
    int B();
}
""");
        Assert.True(result.Success);
        Assert.Contains("export interface IDerived extends IBase<number>", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }
}